<h1><?= te('Time-off requests') ?></h1><?php if($isWorker): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="request"><label><?= te('Assignment') ?></label><select name="placement_id"><?php foreach($assignments as $a): ?><option value="<?= (int)$a['id'] ?>"><?= e($a['title']) ?></option><?php endforeach; ?></select><div class="row"><div><label><?= te('From') ?></label><input type="date" name="starts_on" required></div><div><label><?= te('Through') ?></label><input type="date" name="ends_on" required></div></div><label><?= te('Type') ?></label><input name="request_type" required maxlength="120"><label><?= te('Reason (optional)') ?></label><textarea name="reason"></textarea><button class="btn"><?= te('Request approval') ?></button></form><?php endif; ?><div class="card"><?php foreach($requests as $r): ?><div class="card"><b><?= e(($r['full_name'] ?? '').' · '.$r['project']) ?></b><p><?= e($r['starts_on'].' → '.$r['ends_on'].' · '.$r['request_type'].' · '.$r['status']) ?></p><?php if(!$isWorker && $r['status']==='pending'): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="review"><input type="hidden" name="request_id" value="<?= (int)$r['id'] ?>"><select name="status"><option value="approved"><?= te('approved') ?></option><option value="rejected"><?= te('rejected') ?></option></select><input name="review_note" placeholder="<?= te('Review note') ?>"><button class="btn"><?= te('Decide') ?></button></form><?php endif; ?></div><?php endforeach; ?></div>